package operations
import("fmt";"regexp";"strings";"github.com/jimlucas/zbx-ssh-gateway/internal/config")
func Build(c config.Operation,params map[string]string)(string,error){for k:=range params{if _,ok:=c.Parameters[k];!ok{return "",fmt.Errorf("unknown parameter %q",k)}};values:=map[string]string{};for name,p:=range c.Parameters{v,ok:=params[name];if p.Required&&!ok{return "",fmt.Errorf("parameter %q required",name)};if !ok{continue};if err:=validate(p,v);err!=nil{return "",fmt.Errorf("parameter %q: %w",name,err)};values[name]=v};cmd:=c.Command;for k,v:=range values{cmd=strings.ReplaceAll(cmd,"${"+k+"}",v)};if strings.Contains(cmd,"${"){return "",fmt.Errorf("unresolved parameter in command")};return cmd,nil}
func validate(p config.Parameter,v string)error{switch p.Type{case"enum":for _,x:=range p.Values{if v==x{return nil}};return fmt.Errorf("value not allowed");case"regex":r,e:=regexp.Compile(p.Pattern);if e!=nil{return fmt.Errorf("invalid configured regex")};if !r.MatchString(v){return fmt.Errorf("value does not match pattern")};return nil;case"string":if len(v)>256{return fmt.Errorf("value too long")};return nil;default:return fmt.Errorf("unsupported validator type %q",p.Type)}}
